namespace ghidra.framework.task.gui;






using docking.widgets.list;
using generic.theme;
using generic.theme.GThemeDefaults;
using ghidra.framework.task;
using ghidra.framework.task;
using resources;

public class GTaskResultPanel : JPanel {
	private JList<GTaskResultInfo> jList;
	private CompletedTaskListModel model;

	public GTaskResultPanel(GTaskManager taskMgr) : base(new BorderLayout())
    {
		model = new CompletedTaskListModel(taskMgr);
		jList = new(model);
		jList.setCellRenderer(new GTaskResultCellRenderer());
		JScrollPane scroll = new JScrollPane(jList);
		add(scroll);
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
	}

	static class GTaskResultCellRenderer : GListCellRenderer<GTaskResultInfo> {
		private static readonly Icon CANCELLED_ICON = new GIcon("icon.not.allowed");
		private static readonly Icon EXCEPTION_ICON = Icons.ERROR_ICON;
		private static readonly Icon COMPLETED_ICON = new GIcon("icon.checkmark.green");

		/* @Override */
		protected string getItemText(GTaskResultInfo value) {
			return value.toString();
		}

		/* @Override */
		public Component getListCellRendererComponent(JList<GTaskResultInfo> list,
				GTaskResultInfo value, int index, bool isSelected, bool cellHasFocus) {
			setIcon(getIcon(value.getResult()));
			setBackground(Colors.BACKGROUND);
			return this;
		}

		private Icon getIcon(GTaskResult result) {
			if (result == null) {
				return null;
			}
			if (result.wasCancelled()) {
				return CANCELLED_ICON;
			}
			if (result.getException() != null) {
				return EXCEPTION_ICON;
			}
			return COMPLETED_ICON;
		}
	}
}
